# The default cross-platform benchmark: runs the three portable ONNX models this
# project ships -- Whisper tiny.en (ASR), the Text Scam Classifier (TSC), and the
# FakeAudio / Generated Audio Detector -- through the SAME C++ app on the SAME
# ONNX Runtime, so one command produces a comparable picture on any box (x64 or
# arm64, CPU / GPU / NPU).
#
# Whisper goes through the app's transcribe path (onnx-static backend); the two
# classifiers go through --classify, replaying the pre-baked, validated fixture
# tensors from tools/fixtures/generate.py. Fixtures are auto-generated
# on first run (needs the .venv + the deepfake models present).
#
# Dependency policy: everything here comes from the private HF model repo -- no
# Avast internal repo is involved. Whisper (tools/fetch/get-models.ps1) needs no Python
# to run. The classifier models also come from HF (tools/fetch/get-classifier-models.ps1
# pulls the deepfake/* subtree), but their input fixtures are generated by the Python
# .venv (dump_fixtures.py) since the C++ app doesn't tokenize/embed. When the .venv or
# those models are absent this script SKIPS the classifiers and still runs the full
# HF-hosted Whisper matrix -- so a plain HF checkout benchmarks Whisper end to end.
#
# EP default: the OpenVINO EP (ovep). The benchmark defaults -Provider to "openvino",
# so every device maps to its OpenVINO target (cpu -> openvino:CPU, gpu -> openvino:GPU,
# npu -> openvino:NPU) instead of plain ORT CPU / DirectML. To run the portable,
# vendor-agnostic EP fallback chain instead (VitisAI / QNN / DirectML / OpenVINO / CPU
# -- required on AMD/Qualcomm boxes), pass -Provider auto. Any explicit EP name is
# honored verbatim (e.g. -Provider DmlExecutionProvider, -Provider VitisAIExecutionProvider).
#
#   .\benchmark\run-suite.ps1                       # all three models on OpenVINO CPU
#   .\benchmark\run-suite.ps1 -Device npu           # OpenVINO NPU (Intel AI Boost)
#   .\benchmark\run-suite.ps1 -Device npu,cpu       # sweep several devices (OpenVINO)
#   .\benchmark\run-suite.ps1 -Provider auto        # portable EP fallback chain (non-Intel)
#   .\benchmark\run-suite.ps1 -Precision preferred  # let each executor choose precision
#   .\benchmark\run-suite.ps1 -Only whisper         # just the ASR model
#   .\benchmark\run-suite.ps1 -RegenerateFixtures   # rebuild classifier fixtures first
#
# Startup policy: every model/device gets a dedicated cache that is deleted before
# the run. The C++ harness then creates the session twice against that cache:
# cold = compile from an empty cache; hot = reload the artifact cold just produced.

[CmdletBinding()]
param(
    [ValidateSet("npu", "gpu", "cpu")][string[]]$Device = @("cpu"),
    [ValidateSet("whisper", "tsc", "fakeaudio", "all")][string[]]$Only = @("all"),
    [int]$Runs = 5,
    [int]$ClassifierRuns = 20,
    [string]$Configuration = "Release",
    [string]$Provider = "openvino",
    [ValidateSet("default", "f32", "f16", "bf16", "preferred")]
    [string]$Precision = "default",
    [string]$Audio = "",
    [string]$Results = "",
    [string]$ClassifierResults = "",
    [string]$Manifest = "",
    [string]$AttemptLedger = "",
    [switch]$RegenerateFixtures,
    [switch]$NoResults
)

$ErrorActionPreference = "Stop"
. (Join-Path $PSScriptRoot "lib\harness.ps1")
Initialize-BenchmarkConsole

# "auto" is the escape hatch back to the app's portable per-device EP fallback chain
# (leave --provider off so ort_ep.hpp walks VitisAI/QNN/DirectML/OpenVINO/CPU).
if ($Provider -eq "auto") { $Provider = "" }
if ($Precision -ne "default") {
    $env:NPU_INFERENCE_BENCH_PRECISION = $Precision
}

$root = Split-Path $PSScriptRoot -Parent

# Target the HOST architecture's build tree by default: x64 boxes get build\x64\,
# ARM64 (Snapdragon) boxes get build\ARM64\. Use OSArchitecture so this is correct
# whether PowerShell runs native or x64-emulated on ARM64.
$hostArch = if ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture -eq [System.Runtime.InteropServices.Architecture]::Arm64) { "ARM64" } else { "x64" }
$platform = $hostArch

# The OpenVINO EP lives in a SEPARATE build tree: -EnableOvep emits build\<plat>-ovep\
# (carrying onnxruntime_providers_openvino.dll + the OpenVINO runtime), while a plain
# ORT/DirectML/QNN build emits build\<plat>\. When OpenVINO is the (default) provider,
# target the -ovep build; if it isn't there, fall back to the portable EP chain on the
# plain build rather than failing every run -- and say how to produce the OVEP build.
# Note: there is no OpenVINO EP build for ARM64, so on Snapdragon this always falls
# through to the portable chain (which carries the QNN EP -> Hexagon NPU).
if ($Provider -like "openvino*") {
    $ovepExe = Join-Path $root "build\$hostArch-ovep\$Configuration\NpuInferenceBench.exe"
    if (Test-Path $ovepExe) {
        $platform = "$hostArch-ovep"
    }
    else {
        Write-Host "OpenVINO EP requested ('$Provider') but no OVEP build at build\$hostArch-ovep\$Configuration." -ForegroundColor Yellow
        if ($hostArch -eq "ARM64") {
            Write-Host "  (OpenVINO has no ARM64 EP build; the portable chain uses the QNN EP -> Hexagon NPU instead.)" -ForegroundColor Yellow
        }
        else {
            Write-Host "  -> build it with:  pwsh -File tools\setup\setup-ovep.ps1 ; pwsh -File tools\build\build.ps1 -EnableOvep" -ForegroundColor Yellow
        }
        Write-Host "  Falling back to the portable EP chain (-Provider auto) on the plain build." -ForegroundColor Yellow
        $Provider = ""
    }
}
$exe = Join-Path $root "build\$platform\$Configuration\NpuInferenceBench.exe"
if (-not (Test-Path $exe)) {
    Write-Host "Not built: $exe  (run .\tools\build\build.ps1 -EnableOrt / -EnableOvep or bootstrap.ps1)" -ForegroundColor Red
    exit 1
}

if ($Only -contains "all") { $Only = @("whisper", "tsc", "fakeaudio") }
if (-not $Results) { $Results = Join-Path $root "results\ledgers\asr.csv" }
if (-not $ClassifierResults) { $ClassifierResults = Join-Path $root "results\ledgers\classifiers.csv" }
if (-not $AttemptLedger) { $AttemptLedger = Join-Path $root "results\ledgers\attempts.jsonl" }
if (-not $Manifest) { $Manifest = Join-Path $root "benchmark\manifests\portable.json" }
if (-not $Audio) { $Audio = Join-Path $root "workloads\eval\ls_000.wav" }

if (-not (Test-Path $Manifest)) {
    Write-Host "Benchmark manifest missing: $Manifest" -ForegroundColor Red
    exit 1
}
$workloads = @((Get-Content $Manifest -Raw -Encoding UTF8 | ConvertFrom-Json).workloads)
$fixRoot = Join-Path $root "workloads\classifiers\fixtures"
$classifierFix = @{ tsc = (Join-Path $fixRoot "tsc"); fakeaudio = (Join-Path $fixRoot "fakeaudio") }

# Keep benchmark caches isolated by binary platform + provider + model + device.
# This avoids cross-EP blob contamination and makes deletion safe and targeted.
$providerTag = if ($Provider) { $Provider } else { "auto" }
$providerTag = $providerTag -replace '[^A-Za-z0-9_.-]', '_'
$benchmarkCacheRoot = Join-Path $root "build\cache\benchmark-onnx\$platform\$providerTag"

function New-ColdBenchmarkCache {
    param([string]$ModelTag, [string]$DeviceTag)
    $path = Join-Path $benchmarkCacheRoot "$ModelTag\$DeviceTag"
    if (Test-Path $path) { Remove-Item $path -Recurse -Force }
    New-Item -ItemType Directory -Force -Path $path | Out-Null
    Write-Host "cache      : reset -> $path" -ForegroundColor DarkGray
    return $path
}

# --- best-effort whisper reference (WER) from the eval manifest --------------
function Get-EvalRef {
    param([string]$AudioPath)
    $evalJsonl = Join-Path $root "workloads\eval\eval.jsonl"
    if (-not (Test-Path $evalJsonl)) { return "" }
    $id = [System.IO.Path]::GetFileNameWithoutExtension($AudioPath)
    foreach ($line in Get-Content $evalJsonl) {
        if (-not $line.Trim()) { continue }
        try { $row = $line | ConvertFrom-Json } catch { continue }
        if ($row.id -eq $id) { return [string]$row.ref }
    }
    return ""
}

# --- ensure classifier fixtures exist (generate via the validated Python) ----
function Ensure-Fixtures {
    param([string[]]$Models)
    $need = @()
    foreach ($m in $Models) {
        if ($RegenerateFixtures -or -not (Test-Path (Join-Path $classifierFix[$m] "model.tsv"))) { $need += $m }
    }
    if ($need.Count -eq 0) { return }

    $vpy = Join-Path $root ".venv\Scripts\python.exe"
    if (-not (Test-Path $vpy)) {
        Write-Host "Fixtures missing for: $($need -join ', '); no .venv to generate them (run bootstrap.ps1)." -ForegroundColor Yellow
        return
    }
    Write-Host "Generating classifier fixtures: $($need -join ', ') ..." -ForegroundColor Cyan
    $env:PYTHONUTF8 = "1"; $env:PYTHONIOENCODING = "utf-8"
    & $vpy (Join-Path $root "tools\fixtures\generate.py") --models @need
    if ($LASTEXITCODE -ne 0) {
        Write-Host "Fixture generation failed (models present? deepfake pipeline deps installed?)." -ForegroundColor Yellow
    }
}

$ran = @()
$skipped = @()
$attemptParent = Split-Path $AttemptLedger -Parent
New-Item -ItemType Directory -Force -Path $attemptParent | Out-Null

function Write-Attempt {
    param(
        [object]$Workload,
        [string]$RequestedDevice,
        [string]$Status,
        [string]$ErrorMessage,
        [object]$Result
    )
    $record = [ordered]@{
        timestamp_utc = [DateTime]::UtcNow.ToString("o")
        suite = "portable"
        workload = [string]$Workload.id
        kind = [string]$Workload.kind
        backend = [string]$Workload.backend
        requested_device = $RequestedDevice
        requested_provider = $(if ($Provider) { $Provider } else { "auto" })
        status = $Status
        error = $ErrorMessage
        result = $Result
    }
    Add-Content -LiteralPath $AttemptLedger -Value ($record | ConvertTo-Json -Depth 12 -Compress) -Encoding UTF8
}

function Invoke-NativeBenchmark {
    param([object]$Workload, [string]$RequestedDevice)

    $path = Join-Path $root ([string]$Workload.path -replace '/', '\')
    if (-not (Test-Path $path)) {
        $message = "workload assets missing: $path"
        Write-Host $message -ForegroundColor Yellow
        Write-Attempt $Workload $RequestedDevice "assets-missing" $message $null
        return $false
    }

    $args = @()
    $cache = Join-Path $root "build\cache\$($Workload.id)\$RequestedDevice"
    if (Test-Path $cache) { Remove-Item -LiteralPath $cache -Recurse -Force }
    New-Item -ItemType Directory -Force -Path $cache | Out-Null
    if ($Workload.kind -eq "asr") {
        $args += @("run", "whisper", $path, $Audio, [string]$Workload.backend, $RequestedDevice, "$Runs")
        $args += @("--cache", $cache, "--json")
        $ref = Get-EvalRef -AudioPath $Audio
        if ($ref) { $args += @("--ref", $ref) }
        if (-not $NoResults) { $args += @("--results", $Results, "--label", [string]$Workload.id) }
    } else {
        $args += @("run", [string]$Workload.id, $path, $RequestedDevice, "$ClassifierRuns", "--json")
        $args += @("--cache", $cache)
        if (-not $NoResults) { $args += @("--results", $ClassifierResults) }
    }
    if ($Provider) { $args += @("--provider", $Provider) }

    $oldEap = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try {
        $nativeOutput = @(& $exe @args 2>&1)
        $exitCode = $LASTEXITCODE
    } finally {
        $ErrorActionPreference = $oldEap
    }
    foreach ($line in $nativeOutput) { Write-Host ([string]$line) }
    $result = $null
    for ($i = $nativeOutput.Count - 1; $i -ge 0; --$i) {
        $line = $nativeOutput[$i]
        try {
            $candidate = ([string]$line) | ConvertFrom-Json -ErrorAction Stop
            if ($null -ne $candidate.ok) { $result = $candidate; break }
        } catch {}
    }
    if ($exitCode -eq 0 -and $result -and $result.ok) {
        Write-Attempt $Workload $RequestedDevice "ok" "" $result
        return $true
    }
    $message = if ($result -and $result.error) { [string]$result.error } else { "executor exited with code $exitCode" }
    Write-Attempt $Workload $RequestedDevice "executor-failed" $message $result
    return $false
}

$wantClassifiers = @($Only | Where-Object { $_ -in @("tsc", "fakeaudio") })
if ($wantClassifiers.Count -gt 0) { Ensure-Fixtures -Models $wantClassifiers }

foreach ($dev in $Device) {
    Write-Host "`n==================== device: $dev ====================" -ForegroundColor Magenta

    foreach ($workload in $workloads) {
        $selector = if ($workload.kind -eq "asr") { "whisper" } else { [string]$workload.id }
        if ($Only -notcontains $selector) { continue }
        $tag = "$($workload.id)/$dev"
        if (@($workload.devices) -notcontains $dev) {
            $message = "device '$dev' is unsupported by workload '$($workload.id)'"
            Write-Host $message -ForegroundColor DarkYellow
            Write-Attempt $workload $dev "unsupported" $message $null
            $skipped += $tag
            continue
        }
        Write-Host "`n--- $($workload.id) [$($workload.kind)] ---" -ForegroundColor Cyan
        if (Invoke-NativeBenchmark $workload $dev) { $ran += $tag } else { $skipped += $tag }
    }
}

Write-Host "`n==================== summary ====================" -ForegroundColor Magenta
Write-Host "ran    : $(if ($ran.Count) { $ran -join ', ' } else { '(nothing)' })" -ForegroundColor Green
if ($skipped.Count) { Write-Host "skipped: $($skipped -join ', ')" -ForegroundColor Yellow }
if (-not $NoResults) {
    Write-Host "ASR ledger        : $Results" -ForegroundColor DarkGray
    Write-Host "classifier ledger : $ClassifierResults" -ForegroundColor DarkGray
}
Write-Host "attempt ledger    : $AttemptLedger" -ForegroundColor DarkGray
